mapper.select:
SELECT COALESCE(SUM(count), 0) FROM ai_module_record


        AND module_type = #{moduleType}


        AND record_date = #{date}

WITH RECURSIVE dates AS ( SELECT CURDATE() - INTERVAL 6 DAY AS date_value UNION ALL SELECT date_value + INTERVAL 1 DAY FROM dates WHERE date_value < CURDATE() ) SELECT d.date_value AS date, COALESCE(SUM(r.count), 0) AS count FROM dates d LEFT JOIN ai_module_record r ON r.record_date = d.date_value
AND r.module_type = #{moduleType}
GROUP BY d.date_value ORDER BY d.date_value;

SELECT COALESCE(SUM(count), 0) FROM ai_module_record


        AND user_id = #{userId}


        AND module_type = #{moduleType}

SELECT module_type AS moduleType, COALESCE(SUM(count), 0) AS count FROM ai_module_record
AND record_date = #{date}
GROUP BY module_type
